NS_IMETHODIMP nsMsgDBFolder::UpdateTimestamps(bool userInitiated) {
  if (!(mFlags & (nsMsgFolderFlags::Trash | nsMsgFolderFlags::Junk))) {
    SetMRUTime();
    if (userInitiated) {
      bool isArchive;
      IsSpecialFolder(nsMsgFolderFlags::Archive, true, &isArchive);
      if (!isArchive) {
        SetMRMTime();
      }
    }
  }
  return NS_OK;
}
